                <div style={{ color: theme.success, fontSize: '14px', marginBottom: '5px' }}>✅ Optimal Performance</div>
                <div style={{ color: theme.subtext, fontSize: '12px' }}>
                  Avg response: 85ms<br/>
                  Requests/min: 120<br/>
                  Error rate: 0.1%
                </div>
              </div>
            </div>
          </div>
        )}
      </div>

      {/* Alert Details Modal */}
      {selectedAlert && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.5)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000
        }}>
          <div style={{
            background: theme.cardBg,
            borderRadius: '15px',
            padding: '30px',
            maxWidth: '500px',
            width: '90%',
            maxHeight: '80vh',
            overflow: 'auto'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0, color: theme.text }}>🚨 Alert Details</h3>
              <button
                onClick={() => setSelectedAlert(null)}
                style={{
                  background: 'none',
                  border: 'none',
                  fontSize: '24px',
                  cursor: 'pointer',
                  color: theme.subtext
                }}
              >
                ×
              </button>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>User:</strong> {selectedAlert.user}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Type:</strong> 
                <span style={{
                  background: selectedAlert.type === 'SOS' ? theme.danger : theme.warning,
                  color: 'white',
                  padding: '4px 8px',
                  borderRadius: '12px',
                  fontSize: '12px',
                  marginLeft: '10px'
                }}>
                  {selectedAlert.type?.toUpperCase()}
                </span>
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Location:</strong> {selectedAlert.location}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Time:</strong> {selectedAlert.time}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Status:</strong>
                <span style={{
                  background: selectedAlert.status === 'Active' ? theme.danger : theme.success,
                  color: 'white',
                  padding: '4px 8px',
                  borderRadius: '12px',
                  fontSize: '12px',
                  marginLeft: '10px'
                }}>
                  {selectedAlert.status}
                </span>
              </div>
            </div>

            <div style={{ display: 'flex', gap: '10px' }}>
              {selectedAlert.status === 'Active' && (
                <button
                  onClick={() => {
                    resolveAlert(selectedAlert.id);
                    setSelectedAlert(null);
                  }}
                  style={{
                    background: theme.success,
                    color: 'white',
                    border: 'none',
                    padding: '12px 20px',
                    borderRadius: '8px',
                    fontSize: '14px',
                    cursor: 'pointer',
                    fontWeight: '500'
                  }}
                >
                  Resolve Alert
                </button>
              )}
              <button
                onClick={() => setSelectedAlert(null)}
                style={{
                  background: theme.border,
                  color: theme.text,
                  border: 'none',
                  padding: '12px 20px',
                  borderRadius: '8px',
                  fontSize: '14px',
                  cursor: 'pointer'
                }}
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      {/* User Details Modal */}
      {showUserDetails && (
        <div style={{
          position: 'fixed',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          background: 'rgba(0,0,0,0.5)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          zIndex: 1000
        }}>
          <div style={{
            background: theme.cardBg,
            borderRadius: '15px',
            padding: '30px',
            maxWidth: '500px',
            width: '90%',
            maxHeight: '80vh',
            overflow: 'auto'
          }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
              <h3 style={{ margin: 0, color: theme.text }}>👤 User Details</h3>
              <button
                onClick={() => setShowUserDetails(null)}
                style={{
                  background: 'none',
                  border: 'none',
                  fontSize: '24px',
                  cursor: 'pointer',
                  color: theme.subtext
                }}
              >
                ×
              </button>
            </div>

            <div style={{ marginBottom: '20px' }}>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Name:</strong> {showUserDetails.name}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Email:</strong> {showUserDetails.email}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Status:</strong>
                <span style={{
                  background: showUserDetails.status === 'Active' ? theme.success : theme.warning,
                  color: 'white',
                  padding: '4px 8px',
                  borderRadius: '12px',
                  fontSize: '12px',
                  marginLeft: '10px'
                }}>
                  {showUserDetails.status}
                </span>
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Last Seen:</strong> {showUserDetails.lastSeen}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Join Date:</strong> {showUserDetails.joinDate}
              </div>
              <div style={{ marginBottom: '15px' }}>
                <strong style={{ color: theme.text }}>Emergency Contacts:</strong> {showUserDetails.emergencyContacts || 0}
              </div>
            </div>

            <button
              onClick={() => setShowUserDetails(null)}
              style={{
                background: theme.primary,
                color: 'white',
                border: 'none',
                padding: '12px 20px',
                borderRadius: '8px',
                fontSize: '14px',
                cursor: 'pointer',
                fontWeight: '500'
              }}
            >
              Close
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;
